import{_ as a,c as t,o as s,a3 as o}from"./chunks/framework.Dokpd4od.js";const d=JSON.parse('{"title":"Refuse and reopen an applicant","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/applicants/refuse-and-reopen.md","filePath":"master/human-resources/recruitment/applicants/refuse-and-reopen.md","lastUpdated":1791902625000}'),n={name:"master/human-resources/recruitment/applicants/refuse-and-reopen.md"};function r(i,e,l,p,c,u){return s(),t("div",null,e[0]||(e[0]=[o('<h1 id="refuse-and-reopen-an-applicant" tabindex="-1">Refuse and reopen an applicant <a class="header-anchor" href="#refuse-and-reopen-an-applicant" aria-label="Permalink to &quot;Refuse and reopen an applicant&quot;">​</a></h1><p>Refusing closes an application and records why. The reason helps you see later why people drop out. If you refused by mistake, or the person comes back, you can restore the applicant and continue.</p><blockquote><p><strong>In simple words:</strong> Click <strong>Refuse</strong>, pick a reason, and submit. Click <strong>Restore</strong> to undo it.</p></blockquote><p>Open an applicant from <code>Recruitments → Applications → Applicants</code>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Create your <a href="./../setup/refuse-reasons.html">refuse reasons</a>. Aureus ships with seven, for example <strong>Does not fit the job requirements</strong>, <strong>Duplicate</strong> and <strong>Refused by applicant: salary</strong>.</p></div><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><p>Meera Nair applied for <strong>Warehouse Supervisor</strong>. She declined because of the pay. You record that.</p><ol><li>Open Meera&#39;s applicant page. Click <strong>Refuse</strong> in the header.</li></ol><ol start="2"><li>The <strong>Refuse Reason</strong> window opens. It shows the reasons as buttons. Choose <strong>Refused by applicant: salary</strong>.</li></ol><ol start="3"><li>After you choose a reason, two fields appear. <strong>Notify</strong> is on by default. <strong>Email To</strong> holds the candidate&#39;s email address.</li></ol><ul><li><strong><em>Refuse reason:</em></strong> Required. Pick one button. <strong>Submit</strong> does nothing until you pick one.</li><li><strong><em>Notify:</em></strong> On by default. When it is on, Aureus sends the candidate an email based on the reason&#39;s template.</li><li><strong><em>Email To:</em></strong> Shows only when <strong>Notify</strong> is on. It starts with the candidate&#39;s email address. You can change it.</li></ul><ol start="4"><li>Turn <strong>Notify</strong> off if you do not want to send a message. Click <strong>Submit</strong>.</li></ol><h2 id="what-happens-after-you-refuse" tabindex="-1">What happens after you refuse <a class="header-anchor" href="#what-happens-after-you-refuse" aria-label="Permalink to &quot;What happens after you refuse&quot;">​</a></h2><ul><li>The <strong>Application status</strong> shows <strong>Refused</strong>.</li><li>The stage bar is hidden.</li><li>The applicant becomes inactive and shows under the <strong>Archived</strong> tab of the <a href="./applicant-list.html">applicant list</a>.</li><li>The header now offers <strong>Restore</strong> instead of <strong>Refuse</strong>.</li></ul><p>Each reason uses one of two email templates, <strong>Applicant Refuse</strong> or <strong>Applicant Not Interested</strong>. You choose the template in <a href="./../setup/refuse-reasons.html">Refuse reasons</a>.</p><h2 id="reopen-the-applicant" tabindex="-1">Reopen the applicant <a class="header-anchor" href="#reopen-the-applicant" aria-label="Permalink to &quot;Reopen the applicant&quot;">​</a></h2><ol start="5"><li>Open Meera&#39;s applicant page. Click <strong>Restore</strong> in the header.</li></ol><ol start="6"><li>Confirm in the window that opens.</li></ol><p>Aureus reopens the application. Meera is back in the process and you can click a stage again.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The button is called <strong>Restore</strong>. It is the way to reopen a refused application.</p></div><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Refuse:</strong> closes the application with a reason.</li><li><strong>Restore:</strong> reopens a refused application.</li><li><strong>Refused:</strong> status shown on a turned down applicant.</li><li><strong>Archived:</strong> the list tab that holds inactive applicants.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./process-applicant.html">Process an applicant</a></li><li><a href="./applicant-list.html">Applicant list</a></li><li><a href="./../setup/refuse-reasons.html">Refuse reasons</a></li></ul>',24)]))}const f=a(n,[["render",r]]);export{d as __pageData,f as default};
